using QuanLyThueSanTheThao.Helpers;using QuanLyThueSanTheThao.Services;
namespace QuanLyThueSanTheThao.Forms.Admin;
public partial class FrmSettings:Form
{
    private readonly SettingsService s=new();public FrmSettings(){InitializeComponent();AppTheme.Upgrade(this);ResponsiveHelper.Apply(this);try{var sp=this.Controls.OfType<System.Windows.Forms.SplitContainer>().FirstOrDefault(); if(sp!=null) ResponsiveHelper.FixSplitContainer(sp);}catch{}AppTheme.StylePrimary(btnSave);btnSave.Click+=(_,__)=>Save();Shown+=(_,__)=>LoadData();}
    private void LoadData(){txtCompany.Text=s.Get("CompanyName");txtBankName.Text=s.Get("BankName");txtBankBin.Text=s.Get("BankBin");txtAccount.Text=s.Get("BankAccountNumber");txtAccountName.Text=s.Get("BankAccountName");txtPrefix.Text=s.Get("QrTransferPrefix","THANHTOAN");txtOpen.Text=s.Get("OpenTime","05:00");txtClose.Text=s.Get("CloseTime","23:00");}
    private void Save(){if(string.IsNullOrWhiteSpace(txtCompany.Text)){UiMsg.Warn("Tên hệ thống không được để trống.");return;}if(string.IsNullOrWhiteSpace(txtBankBin.Text)||txtBankBin.Text.Any(c=>!char.IsDigit(c))||string.IsNullOrWhiteSpace(txtAccount.Text)||txtAccount.Text.Any(c=>!char.IsDigit(c))){UiMsg.Warn("Bank BIN và số tài khoản chỉ được chứa chữ số.");return;}if(!TimeSpan.TryParse(txtOpen.Text.Trim(),out var open)||!TimeSpan.TryParse(txtClose.Text.Trim(),out var close)||close<=open){UiMsg.Warn("Giờ hoạt động chưa hợp lệ. Hãy nhập dạng HH:mm và giờ đóng phải sau giờ mở.");return;}try{s.Set("CompanyName",txtCompany.Text.Trim());s.Set("BankName",txtBankName.Text.Trim());s.Set("BankBin",txtBankBin.Text.Trim());s.Set("BankAccountNumber",txtAccount.Text.Trim());s.Set("BankAccountName",txtAccountName.Text.Trim().ToUpperInvariant());s.Set("QrTransferPrefix",string.IsNullOrWhiteSpace(txtPrefix.Text)?"THANHTOAN":txtPrefix.Text.Trim().ToUpperInvariant());s.Set("OpenTime",open.ToString(@"hh\:mm"));s.Set("CloseTime",close.ToString(@"hh\:mm"));Toast.Success("Đã lưu cấu hình.");}catch(Exception ex){UiMsg.Error(ex.Message,"Lưu cấu hình");}}
}
